macro_rules! sum90 {
    ($($item:expr),+ $(,)?) => { 0 $(+ $item)+ };
}

pub fn fold90(values: &[i32]) -> i32 {
    let literal = sum90!(25, 11);
    values.iter().filter(|v| **v >= 0).fold(literal, |acc, v| acc + *v)
}
